const int N = 5;
int a[N] = {4, 9, 2, 7, 10};

// sum and average
int sum = 0;
for (int i = 0; i < N; i++) sum += a[i];   // add each element
double avg = (double)sum / N;               // cast first, then divide

// count elements that pass a test
int count = 0;
for (int i = 0; i < N; i++)
    if (a[i] % 2 == 0) count++;            // even numbers

// copy a into b (b = a is NOT allowed)
for (int i = 0; i < N; i++) b[i] = a[i];

// swap two values with a temporary
int temp = a[0]; a[0] = a[1]; a[1] = temp;

// reverse in place
for (int i = 0; i < N / 2; i++) { int t = a[i]; a[i] = a[N - 1 - i]; a[N - 1 - i] = t; }

// insert x at index pos (n = values in use, array has a spare box)
for (int i = n; i > pos; i--) a[i] = a[i - 1];  // shift right
a[pos] = x;  n++;

// delete the element at index pos
for (int i = pos; i < n - 1; i++) a[i] = a[i + 1];  // shift left
n--;

