#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int marks[N] = {60, 75, 90, 45, 80};
    int sum = 0;
    for (int i = 0; i < N; i++) {
        sum += marks[i];
    }
    double avg = (double)sum / N;
    cout << "Sum = " << sum << endl;
    cout << "Average = " << avg << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int N = 6;
    int a[N] = {4, 9, 2, 7, 10, 3};
    int b[N];
    int sum = 0;
    for (int i = 0; i < N; i++) {
        sum += a[i];
        b[i] = a[i];
    }
    double avg = (double)sum / N;
    int evens = 0, above = 0;
    for (int i = 0; i < N; i++) {
        if (a[i] % 2 == 0) {
            evens++;
        }
        if (a[i] > avg) {
            above++;
        }
    }
    cout << "Average = " << avg << endl;
    cout << "Evens = " << evens << endl;
    cout << "Above average = " << above << endl;
    cout << "Copy: ";
    for (int i = 0; i < N; i++) {
        cout << b[i] << " ";
    }
    cout << endl;
    return 0;
}

