#include <iostream>
using namespace std;
int main() {
    const int N = 5;
    int a[N];
    int sum = 0;
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        sum += a[i];
    }
    double avg = (double)sum / N;
    int count = 0;
    for (int i = 0; i < N; i++) {
        if (a[i] > avg) {
            count++;
        }
    }
    cout << "Above average: " << count << endl;
    return 0;
}
